cypress_script:
describe('Accordian Interaction', () => {
  it('should expand and collapse the accordion sections', () => {
    cy.visit('https://demoqa.com/accordian');
    cy.get('button.accordion-button').contains('What is Lorem Ipsum?').click();
    cy.get('button.accordion-button').contains('What is Lorem Ipsum?').should('not.have.class', 'collapsed');
    cy.get('button.accordion-button').contains('What is Lorem Ipsum?').click();
    cy.get('button.accordion-button').contains('What is Lorem Ipsum?').should('have.class', 'collapsed');
  });

  it('should not change the URL when clicking on collapsed sections', () => {
    cy.visit('https://demoqa.com/accordian');
    cy.url().should('eq', 'https://demoqa.com/accordian');
    cy.get('button.accordion-button.collapsed').contains('Where does it come from?').click();
    cy.url().should('eq', 'https://demoqa.com/accordian');
  });
});

playwright_script:
import { test, expect } from '@playwright/test';

test.describe('Accordian Interaction', () => {
  test('should expand and collapse the accordion sections', async ({ page }) => {
    await page.goto('https://demoqa.com/accordian');
    await page.click('button.accordion-button:has-text("What is Lorem Ipsum?")');
    await expect(page.locator('button.accordion-button:has-text("What is Lorem Ipsum?")')).not.toHaveClass(/collapsed/);
    await page.click('button.accordion-button:has-text("What is Lorem Ipsum?")');
    await expect(page.locator('button.accordion-button:has-text("What is Lorem Ipsum?")')).toHaveClass(/collapsed/);
  });

  test('should not change the URL when clicking on collapsed sections', async ({ page }) => {
    await page.goto('https://demoqa.com/accordian');
    await expect(page).toHaveURL('https://demoqa.com/accordian');
    await page.click('button.accordion-button.collapsed:has-text("Where does it come from?")');
    await expect(page).toHaveURL('https://demoqa.com/accordian');
  });
});
